          ${ selectedLeave.value.status.id === 3 ? 'Talal Abood' : 'no one' }
        </div>
      </td>
    </tr>
  </tbody>
  <tfoot>
    <tr>
      <td style="border: none; text-align: center;">HR</td>
      <td style="border: none; text-align: center;">DIRECTOR</td>
    </tr>
  </tfoot>
</table>

</body>
</html>
`;

    const iframeDoc = iframe.contentWindow.document;
    iframeDoc.open();
    iframeDoc.write(printContent);
    iframeDoc.close();

    iframe.onload = () => {
      iframe.contentWindow.focus();
      iframe.contentWindow.print();
      setTimeout(() => {
        document.body.removeChild(iframe);
      }, 1000);
    };
  } catch (error) {
    showError(`Failed to print report: ${error.message}`);
  }
};

const getReactiveLeaves = async () => {
   const response = await axiosInstance.get('employee-leave')
      leaves.value = response.data.map((item, index) => {
         const start = new Date(item.start_date)
         const end = new Date(item.end_date)
         const leave_days = Math.ceil((end - start) / (1000 * 60 * 60 * 24)) + 1
         return {
            ...item,
            Sno: index + 1,
             attachment: process.env.VUE_APP_API_BASE_URL + '../../' + item.attachment,
             leave_attachment:item.attachment,
            employee: item.employee.name,
            leave_days
         }
      })
}


    onMounted(() => {
         getLeaves()
    });
</script>
